def to_underscore(input):
    if not isinstance(input, str):
        return str(input)
    if not input:
        return input
    result = []
    for i, c in enumerate(input):
        if c.isupper():
            if i != 0:
                result.append('_')
            result.append(c.lower())
        else:
            result.append(c)
    return ''.join(result)
